// Shared locations and the banner for every generated file.
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
export const SHARED = join(ROOT, '..', 'app', 'src', 'main', 'assets', 'web', 'shared');
export const BANNER = '/* Generated by web-ui — do not edit. Run: cd web-ui && npm run build */';
